func ParseConfig(input interface{}, nodeCount int) (Config, error) {
	out := Config{}
	out.setDefaults(nodeCount)

	if input == nil {
		return out, nil
	}

	asMap, ok := input.(map[string]interface{})
	if !ok || asMap == nil {
		return out, fmt.Errorf("input %T-%v must be a non-nil", input, ok)
	}

	if err := optionalIntFromMap(asMap, "virtualPerPhysical", func(v int) {
		out.VirtualPerPhysical = v
	}); err != nil {
		return out, err
	}

	if err := optionalIntFromMap(asMap, "desiredCount", func(v int) {
		out.DesiredCount = v
	}); err != nil {
		return out, err
	}

	out.DesiredVirtualCount = out.DesiredCount * out.VirtualPerPhysical
	// ... actual counts set equal to desired counts
	out.ActualCount = c.DesiredCount
	c.ActualVirtualCount = c.DesiredVirtualCount

	if err := out.validate(); err != nil {
		return out, err
	}

	return out, nil
}

func (c *Config) validate() error {
	if c.Key != "_id" {
		return errors.Errorf("sharding only supported on key '_id' for now, got: %s", c.Key)
	}
	if c.Strategy != "hash" {
		return errors.Errorf("sharding only supported with strategy 'hash' for now, got: %s", c.Strategy)
	}
	return nil // NO RANGE CHECK ON DesiredCount!
